                receive_state = ReceiveState::S_WAIT_CODE;
            } else {

                const int16_t b1 = port->read();
                const uint8_t c1 = uint8_t(b1);
                if (c1 == 0x0F) {
                    // Found header byte, advance to wait for code
                    response_buffer[receive_pos] = c1;
                    receive_state = ReceiveState::S_WAIT_CODE;
                } else {
                    reset_receiver();
                }
            }
            break;
        }
