void AC_AttitudeControl::nonlinear_control_quat(Quaternion& att_to_quat, const Quaternion& att_from_quat, Vector3f& att_diff_angle, float& thrust_vec_dot)
{


	//旋转从机体坐标系到惯性坐标系---- rotation from the target body frame to the inertial frame.
    Matrix3f att_to_rot_matrix;
    //得到惯性坐标系下的方向余弦矩阵，注意att_to_quat已经进行归一化处理了
    att_to_quat.rotation_matrix(att_to_rot_matrix); //目标到实际的地理坐标系下，目标四元数
    //获取垂直矢量
    Vector3f att_to_thrust_vec = att_to_rot_matrix * Vector3f(0.0f, 0.0f, 1.0f); //3*3和3行1列得到地理坐标系下的z轴数据三行一列
    //旋转当前机体坐标系到惯性坐标系-----rotation from the current body frame to the inertial frame.
    Matrix3f att_from_rot_matrix;
    //得到实际的欧拉角的四元数旋转矩阵
    att_from_quat.rotation_matrix(att_from_rot_matrix);  //实际四元数
    //得到实际的垂直信息,n【az,bz,cz】
    Vector3f att_from_thrust_vec = att_from_rot_matrix * Vector3f(0.0f, 0.0f, 1.0f);//得到三行一列

    Quaternion qd_red(att_from_thrust_vec, att_to_thrust_vec);

    thrust_vec_dot = 2.0f * acosf(qd_red.q1);
    if(fabsf(qd_red.q2) > (1.f - 1e-5f) || fabsf(qd_red.q3) > (1.f - 1e-5f))
    {
    	qd_red = att_to_quat;
    }
    else
    {
    	/* transform rotation from current to desired thrust vector into a world frame reduced desired attitude */
    	qd_red *= att_from_quat;  

    }

	/* mix full and reduced desired attitude */
    Quaternion q_mix = qd_red.inverse() * att_to_quat;

    if(q_mix.q1 < 0)
    {
	 q_mix = q_mix * -1.0f;
    }
	/* catch numerical problems with the domain of acosf and asinf */
	q_mix.q1 = constrain_float(q_mix.q1, -1.f, 1.f);
	q_mix.q4 = constrain_float(q_mix.q4, -1.f, 1.f);
	// _yaw_w 【0,1】
	Quaternion qd = qd_red * Quaternion(cosf(_yaw_w  * acosf(q_mix.q1)), 0, 0, sinf(_yaw_w  * asinf(q_mix.q4)));

	/* quaternion attitude control law, qe is rotation from q to qd */
	Quaternion qe = att_from_quat.inverse() * qd;

	att_diff_angle.x = 2.0f *  qe.q2;
	att_diff_angle.y = 2.0f *  qe.q3;
	att_diff_angle.z = 2.0f *  qe.q4;

	if(qe.q1 < 0)
	{
		att_diff_angle = att_diff_angle * -1.0f;
	}
}

